function validate([events, k]) {
  if (!Array.isArray(events) || events.length < 1) return 'events needs at least one event.';
  if (!Number.isInteger(k) || k < 1 || k > events.length) return 'k is between 1 and events.length.';
  if (k * events.length > 1000000) return 'k * events.length is at most 10^6.';
  for (const e of events) {
    if (!Array.isArray(e) || e.length !== 3 || !e.every(Number.isInteger)) return 'Each event is [startDay, endDay, value].';
    if (e[0] < 1 || e[0] > e[1] || e[1] > 1000000000) return 'Days satisfy 1 <= startDay <= endDay <= 10^9.';
    if (e[2] < 1 || e[2] > 1000000) return 'value is between 1 and 10^6.';
  }
  return null;
}

