function maxValue(events, k) {
  const n = events.length;
  let best = 0;
  for (let mask = 1; mask < (1 << n); mask++) {
    const chosen = events.filter((_, i) => mask & (1 << i));
    if (chosen.length > k) continue;
    let ok = true;
    for (let a = 0; a < chosen.length && ok; a++)
      for (let b = a + 1; b < chosen.length && ok; b++)
        if (!(chosen[a][1] < chosen[b][0] || chosen[b][1] < chosen[a][0])) ok = false;
    if (ok) best = Math.max(best, chosen.reduce((sum, e) => sum + e[2], 0));
  }
  return best;
}

