function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'small') {
    const n = int(1, 9);
    const span = int(3, 15);
    const events = Array.from({ length: n }, () => {
      const start = int(1, span);
      const value = rand() < 0.1 ? int(1, 1000000) : int(1, 10);
      return [start, start + int(0, 4), value];
    });
    return [events, int(1, n)];
  }
  const n = 2000;
  const k = int(1, 500);
  const dense = rand() < 0.5;
  const events = Array.from({ length: n }, () => {
    if (dense) {
      const start = int(1, 20000);
      return [start, start + int(0, 60), int(1, 1000000)];
    }
    const start = int(1, 999000000);
    return [start, start + int(0, 1000000), int(1, 1000000)];
  });
  return [events, k];
}
